package com.fuao.harness.protocol;

import java.security.SecureRandom;
import java.util.UUID;

/**
 * Identifier minting. The whole system uses UUIDv7 (01 §4) plus a typed prefix, so that
 * ids stay unique across organisations when harnesses federate (M3) and can also be
 * generated by a terminal that is temporarily offline.
 *
 * <pre>
 *   agent:{uuid7}   terminal:{uuid7}   evt:{uuid7}   cmd:{uuid7}   cap:{uuid7}
 *   exp:{uuid7}     inc:{uuid7}        plan:{uuid7}  grant:{uuid7}  appr:{uuid7}
 *   natural person  emp:{portal_employee_id}          (not minted here - portal owns it)
 *   task            task:{portal_mission_id}          (not minted here - portal owns it)
 * </pre>
 *
 * <p><b>What goes in the database.</b> Columns declared {@code CHAR(36)} hold the <em>bare</em>
 * UUIDv7; the {@code prefix:} form is a display and cross-reference convention used in audit rows,
 * logs, tokens and API payloads. Storing the prefixed form in a {@code CHAR(36)} column is a
 * truncation bug waiting to happen (errata E-08).
 *
 * <p>UUIDv7 layout (RFC 9562): 48 bits of unix millis, 4 bits version (7), 12 bits of
 * monotonic counter (so ids minted inside the same millisecond still sort in creation order),
 * 2 bits variant, 62 random bits.
 */
public final class Ids {

    private Ids() {
    }

    public static final String PREFIX_AGENT = "agent:";
    public static final String PREFIX_TERMINAL = "term:";
    public static final String PREFIX_EVENT = "evt:";
    public static final String PREFIX_COMMAND = "cmd:";
    public static final String PREFIX_CAPABILITY = "cap:";
    public static final String PREFIX_EXPERIENCE = "exp:";
    public static final String PREFIX_INCIDENT = "inc:";
    public static final String PREFIX_PLAN = "plan:";
    public static final String PREFIX_ACTION = "act:";
    public static final String PREFIX_SKILL = "skill:";
    public static final String PREFIX_GRANT = "grant:";
    public static final String PREFIX_APPROVAL = "appr:";
    public static final String PREFIX_PRINCIPAL = "prin:";

    private static final SecureRandom RANDOM = new SecureRandom();

    private static final Object MONOTONIC_LOCK = new Object();
    private static long lastMillis = -1L;
    private static int counter = 0;

    /** A new time-ordered UUIDv7, guaranteed non-decreasing within this process. */
    public static UUID uuid7() {
        long wallClock = System.currentTimeMillis();
        long millis;
        int seq;
        synchronized (MONOTONIC_LOCK) {
            // Never step backwards: an NTP correction must not produce ids that sort before ids
            // already handed out, so the generator clamps to its own high-water mark.
            millis = Math.max(wallClock, lastMillis);
            if (millis == lastMillis) {
                int next = (counter + 1) & 0x0FFF;
                if (next == 0) {
                    // 12-bit counter wrapped inside one millisecond: borrow the next millisecond
                    // so ids keep sorting in creation order.
                    millis = lastMillis + 1;
                }
                seq = next;
            } else {
                seq = 0;
            }
            lastMillis = millis;
            counter = seq;
        }

        byte[] random = new byte[8];
        RANDOM.nextBytes(random);
        long rand62 = 0L;
        for (byte b : random) {
            rand62 = (rand62 << 8) | (b & 0xFFL);
        }
        rand62 &= 0x3FFFFFFFFFFFFFFFL; // keep 62 bits

        long msb = ((millis & 0xFFFFFFFFL) << 32)      // timeLow  (bits 63..32)
                | (((millis >>> 32) & 0xFFFFL) << 16)   // timeMid  (bits 47..32)
                | (0x7L << 12)                         // version 7 (bits 15..12)
                | ((long) seq & 0x0FFFL);               // rand_a   (bits 11..0) <- the counter

        long lsb = (0x2L << 62)                         // variant 0b10 (bits 63..62)
                | (rand62 & 0x3FFFFFFFFFFFFFFFL);       // rand_b   (62 bits)

        return new UUID(msb, lsb);
    }

    /** Bare UUIDv7 string, the form stored in {@code CHAR(36)} columns. */
    public static String newId() {
        return uuid7().toString();
    }

    /** Prefixed id, the form used in logs, tokens and cross-system references. */
    public static String newId(String prefix) {
        return prefix + newId();
    }

    /** Unix millis embedded in a UUIDv7. */
    public static long timestampOf(UUID uuid) {
        long msb = uuid.getMostSignificantBits();
        long low32 = (msb >>> 32) & 0xFFFFFFFFL;
        long high16 = (msb >>> 16) & 0xFFFFL;
        return low32 | (high16 << 32);
    }

    /** Strips a known prefix if present. */
    public static String stripPrefix(String id) {
        int i = id.indexOf(':');
        return i < 0 ? id : id.substring(i + 1);
    }
}